package com.example;

import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

public class QuestProgressOverlay extends ProgressBarOverlayBase
{
    private final Client client;

    @Inject
    public QuestProgressOverlay(Client client, ExampleConfig config)
    {
        super(config);
        this.client = client;
    }

    @Override
    protected boolean isEnabled()
    {
        return config.showQuestProgressBar();
    }

    @Override
    protected int getBarWidth()
    {
        return config.questProgressWidth();
    }

    @Override
    protected int getBarHeight()
    {
        return config.questProgressHeight();
    }

    @Override
    protected Color getBarColor()
    {
        return config.questProgressColor();
    }

    @Override
    protected String getIconText()
    {
        return "Q";
    }

    @Override
    protected ProgressData getProgressData()
    {
        int complete = 0;
        int total = 0;

        for (Quest quest : Quest.values())
        {
            QuestState state = quest.getState(client);

            if (state == null)
            {
                continue;
            }

            total++;

            if (state == QuestState.FINISHED)
            {
                complete++;
            }
        }

        return new ProgressData("Quests " + complete + "/" + total, complete, total);
    }
}

package com.example;

import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

public class XpProgressOverlay extends ProgressBarOverlayBase
{
    private final Client client;
    private Skill mostRecentSkill = Skill.ATTACK;

    @Inject
    public XpProgressOverlay(Client client, ExampleConfig config)
    {
        super(config);
        this.client = client;
    }

    public void setMostRecentSkill(Skill skill)
    {
        if (skill == null || skill == Skill.OVERALL)
        {
            return;
        }

        if (config.progressIgnoreHitpoints() && skill == Skill.HITPOINTS)
        {
            return;
        }

        mostRecentSkill = skill;
    }

    @Override
    protected boolean isEnabled()
    {
        return config.showXpProgressBar();
    }

    @Override
    protected int getBarWidth()
    {
        return config.xpProgressWidth();
    }

    @Override
    protected int getBarHeight()
    {
        return config.xpProgressHeight();
    }

    @Override
    protected Color getBarColor()
    {
        return config.xpProgressColor();
    }

    @Override
    protected String getIconText()
    {
        return "XP";
    }

    @Override
    protected ProgressData getProgressData()
    {
        Skill skill = mostRecentSkill;

        int level = client.getRealSkillLevel(skill);
        int xp = client.getSkillExperience(skill);

        if (level >= 99)
        {
            return new ProgressData(skill.getName() + " 99", 1, 1);
        }

        int currentLevelXp = Experience.getXpForLevel(level);
        int nextLevelXp = Experience.getXpForLevel(level + 1);

        int current = xp - currentLevelXp;
        int max = nextLevelXp - currentLevelXp;

        return new ProgressData(skill.getName() + " " + current + "/" + max, current, max);
    }
}

package com.example;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ExpandedMenuOverlay extends Overlay
{
    private final Client client;
    private final ExampleConfig config;

    @Inject
    ExpandedMenuOverlay(Client client, ExampleConfig config)
    {
        this.client = client;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_HIGH);
        setMovable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        Font originalFont = graphics.getFont();
        Color originalColor = graphics.getColor();

        Font labelFont = originalFont.deriveFont(Font.BOLD, (float) config.fontSize());
        graphics.setFont(labelFont);

        for (ExpandedMenuStone stone : ExpandedMenuStone.values())
        {
            String label = cleanLabel(stone.getLabel(config));

            if (label.isEmpty())
            {
                continue;
            }

            Widget widget = findVisibleWidget(stone);

            if (widget == null)
            {
                continue;
            }

            drawLabel(graphics, widget.getBounds(), label);
        }

        graphics.setFont(originalFont);
        graphics.setColor(originalColor);

        return null;
    }

    private Widget findVisibleWidget(ExpandedMenuStone stone)
    {
        for (int componentId : stone.getComponentIds())
        {
            Widget widget = client.getWidget(componentId);

            if (isDrawable(widget))
            {
                return widget;
            }
        }

        return null;
    }

    private boolean isDrawable(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return false;
        }

        Rectangle bounds = widget.getBounds();

        return bounds != null && bounds.width > 0 && bounds.height > 0;
    }

    private String cleanLabel(String label)
    {
        if (label == null)
        {
            return "";
        }

        return label.trim();
    }

    private void drawLabel(Graphics2D graphics, Rectangle bounds, String label)
    {
        FontMetrics metrics = graphics.getFontMetrics();

        int textWidth = metrics.stringWidth(label);
        int x = bounds.x + bounds.width - textWidth - config.xOffset();
        int y = bounds.y + metrics.getAscent() + config.yOffset();

        if (config.showShadow())
        {
            graphics.setColor(safeColor(config.shadowColor(), Color.BLACK));
            graphics.drawString(label, x + 1, y + 1);
        }

        graphics.setColor(safeColor(config.labelColor(), Color.WHITE));
        graphics.drawString(label, x, y);
    }

    private Color safeColor(Color color, Color fallback)
    {
        return color == null ? fallback : color;
    }
}

